async fn post_config_stpm(JsonBody(new_config): JsonBody<StpmConfig>) -> impl IntoResponse {
    let mut state = STATE.lock().await;
    let state = state.as_mut().unwrap();

    state.stpm = new_config.clone();
    CONFIG_STPM.signal(new_config);
}

